import { fileURLToPath } from 'node:url';
import { protectedPreview } from '../boost-nine/server.mjs';

// RWA-only protected QA preview. Do not use for public release.
// The final public read-only candidate is generated by build.mjs.
export function createRwaPrivateServer({username,password}){
  return protectedPreview({username,password,rwaOnly:true});
}

if(process.argv[1]===fileURLToPath(import.meta.url)){
  const port=Number(process.env.PORT||10000);
  const app=createRwaPrivateServer({
    username:process.env.PREVIEW_USER,
    password:process.env.PREVIEW_PASSWORD
  });
  app.listen(port,'0.0.0.0',()=>process.stdout.write('RWA protected QA preview ready\n'));
}
